from .store import connect

class Ledger:
    def __init__(self, path):
        self.db = connect(path)

    def close(self):
        self.db.close()

    def add_account(self, name, balance):
        with self.db:
            self.db.execute('INSERT INTO accounts VALUES (?, ?)', (name, balance))

    def balance(self, name):
        row = self.db.execute('SELECT balance FROM accounts WHERE name = ?', (name,)).fetchone()
        if row is None:
            raise ValueError('unknown account')
        return row[0]

    def transfer(self, source, destination, amount, request_key=None):
        if type(amount) is not int or amount <= 0:
            raise ValueError('amount must be positive integer cents')
        if source == destination:
            raise ValueError('source and destination must be different accounts')
        if request_key is not None and (not isinstance(request_key, str) or not request_key):
            raise ValueError('request_key must be a nonempty string')
        with self.db:
            # Lock before reading so concurrent requests cannot both apply a transfer.
            self.db.execute('BEGIN IMMEDIATE')
            if request_key is not None:
                existing = self.db.execute('''
                    SELECT transfers.id, source, destination, amount
                    FROM transfer_requests
                    JOIN transfers ON transfers.id = transfer_requests.transfer_id
                    WHERE request_key = ?
                ''', (request_key,)).fetchone()
                if existing is not None:
                    if existing[1:] != (source, destination, amount):
                        raise ValueError('request_key already used for different transfer arguments')
                    return existing[0]
            if self.balance(source) < amount:
                raise ValueError('insufficient funds')
            self.balance(destination)
            self.db.execute('UPDATE accounts SET balance = balance - ? WHERE name = ?', (amount, source))
            self.db.execute('UPDATE accounts SET balance = balance + ? WHERE name = ?', (amount, destination))
            row = self.db.execute('INSERT INTO transfers (source, destination, amount) VALUES (?, ?, ?)', (source, destination, amount))
            transfer_id = row.lastrowid
            if request_key is not None:
                self.db.execute('INSERT INTO transfer_requests (request_key, transfer_id) VALUES (?, ?)', (request_key, transfer_id))
            return transfer_id

