import unittest

from utilities.duration import parse_duration


class ParseDurationTests(unittest.TestCase):
    def test_accepted_formats(self):
        examples = {
            "2h15m": 8100,
            "45s": 45,
            "0s": 0,
            "1h0m4s": 3604,
            "3h": 10800,
            "5m": 300,
            "2h3s": 7203,
            "4m5s": 245,
            "0h0m0s": 0,
            "0002h0015m0004s": 8104,
            "90m120s": 5520,
        }
        for text, expected in examples.items():
            with self.subTest(text=text):
                result = parse_duration(text)
                self.assertEqual(result, expected)
                self.assertIsInstance(result, int)

    def test_components_exceed_decimal_conversion_limit(self):
        digits = "9" * 5000
        component = 10**5000 - 1
        for unit, multiplier in (("h", 3600), ("m", 60), ("s", 1)):
            with self.subTest(unit=unit):
                self.assertEqual(parse_duration(digits + unit), component * multiplier)
        self.assertEqual(parse_duration("0" * 5000 + "1s"), 1)

    def test_rejects_empty_and_whitespace(self):
        self.assert_invalid("", " ", "\t", "\n", " 1h", "1h ", "1h 2m", "1\tm", "1s\n")

    def test_rejects_signs_and_fractions(self):
        self.assert_invalid("+1h", "-1s", "1h+2m", "1h-2m", "1.5h", ".5m", "1/2s", "1e2s")

    def test_rejects_missing_units_and_numbers(self):
        self.assert_invalid("1", "123", "1h2", "1h2m3", "h", "m", "s", "1hm", "1hms")

    def test_rejects_repeated_and_reordered_units(self):
        self.assert_invalid(
            "1h2h", "1m2m", "1s2s", "1h2m3m", "1m2h", "1s2m", "1s2h", "1h2s3m", "0s0h"
        )

    def test_rejects_trailing_garbage_and_unknown_units(self):
        self.assert_invalid("1sx", "1s!", "1s2", "1h,2m", "1d", "1H", "1M", "1S", "1ms", "1s\x00")

    def test_rejects_non_ascii_digits(self):
        self.assert_invalid("١s", "１h", "²m", "𝟙s", "1h٢m", "1２s")

    def test_rejects_non_string_inputs(self):
        self.assert_invalid(None, 1, 1.5, True, b"1s", bytearray(b"1s"), ["1s"], {"s": 1}, object())

    def assert_invalid(self, *values):
        for value in values:
            with self.subTest(value=value):
                with self.assertRaises(ValueError):
                    parse_duration(value)


if __name__ == "__main__":
    unittest.main()

