import copy
import unittest

from utilities.redaction import redact


class RedactionTests(unittest.TestCase):
    def test_traverses_nested_dictionaries_and_lists(self):
        value = {
            'items': [
                {'Secret': 'first', 'name': 'Ada'},
                [{'secret': 'second'}, 'visible', 3],
            ],
            'profile': {'nested': {'SECRET': 'third'}},
        }

        self.assertEqual(
            redact(value, ['secret']),
            {
                'items': [
                    {'Secret': '[REDACTED]', 'name': 'Ada'},
                    [{'secret': '[REDACTED]'}, 'visible', 3],
                ],
                'profile': {'nested': {'SECRET': '[REDACTED]'}},
            },
        )

    def test_matching_keys_replace_whole_container_and_scalar_values(self):
        for sensitive_value in ({'public': 'visible'}, ['visible', {'key': 1}], None, 0):
            with self.subTest(sensitive_value=sensitive_value):
                self.assertEqual(
                    redact({'secret': sensitive_value}, ['secret']),
                    {'secret': '[REDACTED]'},
                )

    def test_matching_is_exact_and_case_insensitive_and_preserves_spelling(self):
        value = {
            'PaSsWoRd': 'hidden',
            'password_hint': 'MiXeD Case',
            'prefix_password': 'visible',
            ' password': 'leading space',
            'password ': 'trailing space',
            'SÉCRET': 'hidden too',
        }

        self.assertEqual(
            redact(value, ['PASSWORD', 'sécret']),
            {
                'PaSsWoRd': '[REDACTED]',
                'password_hint': 'MiXeD Case',
                'prefix_password': 'visible',
                ' password': 'leading space',
                'password ': 'trailing space',
                'SÉCRET': '[REDACTED]',
            },
        )

    def test_sensitive_keys_accepts_reusable_and_one_shot_iterables(self):
        iterable_factories = (
            list,
            tuple,
            set,
            iter,
            lambda values: (value for value in values),
        )
        value = [{'Secret': 1}, {'nested': {'TOKEN': 2, 'secret': 3}}]
        expected = [
            {'Secret': '[REDACTED]'},
            {'nested': {'TOKEN': '[REDACTED]', 'secret': '[REDACTED]'}},
        ]

        for factory in iterable_factories:
            with self.subTest(factory=factory):
                self.assertEqual(redact(value, factory(['secret', 'token'])), expected)

    def test_scalars_remain_unchanged(self):
        for value in (None, True, False, 0, -2, 1.25, '', 'SeCrEt'):
            with self.subTest(value=value):
                self.assertIs(redact(value, ['secret']), value)

    def test_input_is_unchanged_and_retained_containers_are_fresh(self):
        value = {
            'secret': {'hidden': ['private']},
            'public': [{'items': ['visible'], 'empty': {}}, []],
        }
        original = copy.deepcopy(value)

        result = redact(value, ['secret'])

        self.assertEqual(value, original)
        self.assertIsNot(result, value)
        self.assertIsNot(result['public'], value['public'])
        self.assertIsNot(result['public'][0], value['public'][0])
        self.assertIsNot(result['public'][0]['items'], value['public'][0]['items'])
        self.assertIsNot(result['public'][0]['empty'], value['public'][0]['empty'])
        self.assertIsNot(result['public'][1], value['public'][1])
        result['public'][0]['items'].append('new')
        self.assertEqual(value, original)

    def test_empty_sensitive_iterable_still_copies_containers(self):
        value = [{'secret': ['visible']}]

        result = redact(value, iter(()))

        self.assertEqual(result, value)
        self.assertIsNot(result, value)
        self.assertIsNot(result[0], value[0])
        self.assertIsNot(result[0]['secret'], value[0]['secret'])


if __name__ == '__main__':
    unittest.main()

