def redact(value, sensitive_keys):
    """Copy a JSON-like tree, replacing values under sensitive dictionary keys."""
    matching_keys = {key.casefold() for key in sensitive_keys}

    def visit(current):
        if isinstance(current, dict):
            return {
                key: '[REDACTED]' if key.casefold() in matching_keys else visit(item)
                for key, item in current.items()
            }
        if isinstance(current, list):
            return [visit(item) for item in current]
        return current

    return visit(value)

