import csv
from io import StringIO


def _format_cell(value):
    if value is None:
        return ""
    if isinstance(value, str):
        if value.lstrip(" \t").startswith(("=", "+", "-", "@")):
            return "'" + value
        return value
    return str(value)


def _write_row(output, values):
    record = StringIO(newline="")
    writer = csv.writer(record, lineterminator="\r\n")
    writer.writerow(_format_cell(value) for value in values)
    # CRLF makes csv.writer quote both CR and LF inside fields. Replace only
    # the record terminator so embedded newlines retain their original text.
    output.write(record.getvalue()[:-2])
    output.write("\n")


def export_csv(rows, columns):
    columns = tuple(columns)
    output = StringIO(newline="")
    _write_row(output, columns)
    for row in rows:
        _write_row(output, (row.get(column) for column in columns))
    return output.getvalue()

