import unittest

from utilities.redaction import redact


class RedactionTests(unittest.TestCase):
    def test_matches_exact_keys_without_changing_other_spelling_or_values(self):
        value = {
            "PaSsWoRd": "hidden",
            "password_hint": "visible",
            " password": "also visible",
            "Label": "PASSWORD",
        }

        self.assertEqual(
            redact(value, ["PASSWORD"]),
            {
                "PaSsWoRd": "[REDACTED]",
                "password_hint": "visible",
                " password": "also visible",
                "Label": "PASSWORD",
            },
        )

    def test_traverses_nested_dictionaries_and_lists_with_one_shot_keys(self):
        value = [
            {"Secret": "first"},
            {"children": [{"SECRET": "second"}, [None, {"TOKEN": "third"}]]},
        ]
        sensitive_keys = (key for key in ["secret", "token"])

        self.assertEqual(
            redact(value, sensitive_keys),
            [
                {"Secret": "[REDACTED]"},
                {
                    "children": [
                        {"SECRET": "[REDACTED]"},
                        [None, {"TOKEN": "[REDACTED]"}],
                    ]
                },
            ],
        )

    def test_matching_keys_replace_entire_values(self):
        for hidden_value in (None, False, 0, "text", [1, {"visible": 2}], {"visible": [3]}):
            with self.subTest(hidden_value=hidden_value):
                self.assertEqual(
                    redact({"secret": hidden_value}, ["secret"]),
                    {"secret": "[REDACTED]"},
                )

    def test_returns_independent_containers_without_mutating_input(self):
        value = {"visible": [{"name": "original"}], "secret": {"data": [1]}}

        result = redact(value, ["secret"])

        self.assertEqual(
            value,
            {"visible": [{"name": "original"}], "secret": {"data": [1]}},
        )
        self.assertIsNot(result, value)
        self.assertIsNot(result["visible"], value["visible"])
        self.assertIsNot(result["visible"][0], value["visible"][0])
        result["visible"][0]["name"] = "changed"
        self.assertEqual(value["visible"][0]["name"], "original")

    def test_empty_key_iterable_still_copies_all_containers(self):
        value = {"items": [[], {}]}

        result = redact(value, iter(()))

        self.assertEqual(result, value)
        self.assertIsNot(result, value)
        self.assertIsNot(result["items"], value["items"])
        self.assertIsNot(result["items"][0], value["items"][0])
        self.assertIsNot(result["items"][1], value["items"][1])

    def test_scalars_are_unchanged(self):
        for value in (None, True, False, 0, -5, 1.25, "SeCrEt"):
            with self.subTest(value=value):
                self.assertEqual(redact(value, ["secret"]), value)

