def redact(value, sensitive_keys):
    """Copy a JSON-like tree, replacing values under sensitive dictionary keys."""
    normalized_keys = {key.casefold() for key in sensitive_keys}

    def copy_value(item):
        if isinstance(item, dict):
            return {
                key: "[REDACTED]" if key.casefold() in normalized_keys else copy_value(value)
                for key, value in item.items()
            }
        if isinstance(item, list):
            return [copy_value(value) for value in item]
        return item

    return copy_value(value)

