import csv
import io


def _cell_text(value):
    if value is None:
        return ""
    if isinstance(value, str) and value.lstrip(" \t").startswith(("=", "+", "-", "@")):
        return "'" + value
    return str(value)


def _csv_record(values):
    output = io.StringIO(newline="")
    # CRLF makes the CSV writer quote both CR and LF inside cells. Replace only
    # this record's terminator so embedded line endings retain their spelling.
    csv.writer(output, lineterminator="\r\n").writerow(values)
    return output.getvalue()[:-2] + "\n"


def export_csv(rows, columns):
    """Return ordered CSV records, protecting string cells from formulas."""
    columns = tuple(columns)
    records = [_csv_record(_cell_text(column) for column in columns)]
    for row in rows:
        records.append(_csv_record(_cell_text(row.get(column)) for column in columns))
    return "".join(records)

