import unittest

from utilities.duration import parse_duration


class ParseDurationTests(unittest.TestCase):
    def test_valid_unit_combinations(self):
        examples = {
            "2h": 7200,
            "15m": 900,
            "45s": 45,
            "2h15m": 8100,
            "1h4s": 3604,
            "2m3s": 123,
            "1h2m3s": 3723,
        }
        for text, expected in examples.items():
            with self.subTest(text=text):
                result = parse_duration(text)
                self.assertEqual(result, expected)
                self.assertIs(type(result), int)

    def test_zero_and_leading_zero_components(self):
        for text, expected in (("0s", 0), ("0h0m0s", 0), ("001h00m04s", 3604)):
            with self.subTest(text=text):
                self.assertEqual(parse_duration(text), expected)

    def test_components_are_not_clock_fields(self):
        self.assertEqual(parse_duration("2h120m90s"), 14490)

    def test_components_have_no_fixed_integer_bound(self):
        digits = "9" * 4500
        component = 10**4500 - 1
        for unit, multiplier in (("h", 3600), ("m", 60), ("s", 1)):
            with self.subTest(unit=unit):
                self.assertEqual(parse_duration(digits + unit), component * multiplier)

    def test_rejects_empty_or_whitespace(self):
        for text in ("", " ", "\t", "\n", " 1s", "1s ", "1 h", "1h 2m", "1s\n", "1\u00a0s"):
            with self.subTest(text=text):
                with self.assertRaises(ValueError):
                    parse_duration(text)

    def test_rejects_signed_fractional_or_non_ascii_numbers(self):
        for text in ("+1s", "-1s", "1h-2m", "1.5h", ".5s", "1e3s", "1_000s", "١s", "１h", "²m"):
            with self.subTest(text=text):
                with self.assertRaises(ValueError):
                    parse_duration(text)

    def test_rejects_missing_units_and_garbage(self):
        for text in ("1", "h", "1h2", "1H", "1d", "1ms", "1sfoo", "1h!", "1s\x00"):
            with self.subTest(text=text):
                with self.assertRaises(ValueError):
                    parse_duration(text)

    def test_rejects_repeated_or_reordered_units(self):
        for text in ("1h2h", "1m2m", "1s2s", "1m2h", "1s2m", "1s2h", "1h2s3m", "0s0h"):
            with self.subTest(text=text):
                with self.assertRaises(ValueError):
                    parse_duration(text)

    def test_rejects_non_strings(self):
        for value in (None, True, 1, 1.5, b"1s", ["1s"], {"duration": "1s"}, object()):
            with self.subTest(value=value):
                with self.assertRaises(ValueError):
                    parse_duration(value)


