import copy
import csv
import io
import unittest

from utilities.tabular import export_csv


class ExportCsvTests(unittest.TestCase):
    def test_preserves_column_order_and_ignores_unselected_fields(self):
        rows = [{"first": "A", "second": "B", "extra": "ignored"}]

        self.assertEqual(export_csv(rows, ["second", "first"]), "second,first\nB,A\n")

    def test_accepts_one_shot_rows(self):
        rows = iter([{"name": "A"}, {"name": "B"}])

        self.assertEqual(export_csv(rows, ["name"]), "name\nA\nB\n")

    def test_empty_rows_still_produce_header(self):
        self.assertEqual(export_csv(iter(()), ["second", "first"]), "second,first\n")

    def test_missing_and_none_are_empty_and_other_scalars_use_str(self):
        rows = [{"none": None, "integer": -12, "float": -1.5, "bool": False}]

        self.assertEqual(
            export_csv(rows, ["missing", "none", "integer", "float", "bool"]),
            "missing,none,integer,float,bool\n,,-12,-1.5,False\n",
        )

    def test_quotes_commas_double_quotes_and_newlines(self):
        rows = [{"comma,name": 'A,"B"\nC'}]

        self.assertEqual(
            export_csv(rows, ["comma,name"]),
            '"comma,name"\n"A,""B""\nC"\n',
        )

    def test_preserves_carriage_returns_and_crlf_inside_cells(self):
        values = ["a\rb", "c\r\nd", "e\nf"]
        result = export_csv(({"value": value} for value in values), ["value"])

        self.assertEqual(result, 'value\n"a\rb"\n"c\r\nd"\n"e\nf"\n')
        self.assertEqual(
            list(csv.reader(io.StringIO(result, newline=""))),
            [["value"], *[[value] for value in values]],
        )

