def parse_duration(text):
    """Return seconds for unsigned integer components in descending h/m/s order."""
    if not isinstance(text, str) or not text:
        raise ValueError("Duration must be a non-empty string")

    unit_seconds = {"h": 3600, "m": 60, "s": 1}
    previous_multiplier = None
    total_seconds = 0
    position = 0

    while position < len(text):
        component_start = position
        component = 0
        while position < len(text) and "0" <= text[position] <= "9":
            # Avoid int(text): Python limits decimal string conversions by default.
            component = component * 10 + ord(text[position]) - ord("0")
            position += 1

        if position == component_start or position == len(text):
            raise ValueError("Each duration component needs ASCII digits and a unit")

        multiplier = unit_seconds.get(text[position])
        if multiplier is None or (
            previous_multiplier is not None and multiplier >= previous_multiplier
        ):
            raise ValueError("Duration units must occur once in h, m, s order")

        total_seconds += component * multiplier
        previous_multiplier = multiplier
        position += 1

    return total_seconds

