            'SECRET': '[REDACTED]',
            'secret_note': 'Visible',
            'mysecret': 'Still Visible',
            ' Secret': 'Keep spaces',
        })

    def test_traverses_nested_dictionaries_and_lists(self):
        value = {
            'Users': [
                {'Name': 'Alice', 'Password': 'first'},
                [{'Name': 'Bob', 'PASSWORD': 'second'}],
            ],
            'Settings': {'Nested': {'password': 'third'}},
        }

        self.assertEqual(redact(value, ['password']), {
            'Users': [
                {'Name': 'Alice', 'Password': '[REDACTED]'},
                [{'Name': 'Bob', 'PASSWORD': '[REDACTED]'}],
            ],
            'Settings': {'Nested': {'password': '[REDACTED]'}},
        })

    def test_matching_keys_replace_the_entire_value(self):
        for sensitive_value in ({'Visible': 'nested'}, ['nested', {'a': 1}], None, 0):
            with self.subTest(sensitive_value=sensitive_value):
                self.assertEqual(
                    redact({'Secret': sensitive_value}, ['secret']),
                    {'Secret': '[REDACTED]'},
                )

    def test_scalars_are_unchanged(self):
        for value in (None, True, False, 0, -17, 3.5, 'Secret', '[REDACTED]'):
            with self.subTest(value=value):
                self.assertIs(redact(value, ['secret']), value)

    def test_sensitive_keys_accepts_different_iterables(self):
        iterables = [
            ['Secret', 'Token'],
            ('Secret', 'Token'),
            {'Secret', 'Token'},
            iter(['Secret', 'Token']),
            (key for key in ['Secret', 'Token']),
        ]
        value = [{'secret': 'one'}, {'TOKEN': 'two', 'secret': 'three'}]
        expected = [
            {'secret': '[REDACTED]'},
            {'TOKEN': '[REDACTED]', 'secret': '[REDACTED]'},
        ]

        for sensitive_keys in iterables:
            with self.subTest(iterable_type=type(sensitive_keys).__name__):
                self.assertEqual(redact(value, sensitive_keys), expected)

    def test_empty_sensitive_keys_still_copies_containers(self):
