        self.assertEqual(result, value)
        self.assertIsNot(result, value)
        self.assertIsNot(result['Nested'], value['Nested'])
        self.assertIsNot(result['Nested'][0], value['Nested'][0])
        self.assertIsNot(result['Nested'][0]['Visible'], value['Nested'][0]['Visible'])

    def test_input_is_unchanged_and_output_containers_are_independent(self):
        value = {
            'Secret': {'private': ['original']},
