        })
        result['Visible'][0]['Label'] = 'Changed'
        result['Visible'][0]['Values'].append(3)
        result['Visible'].append({})
        self.assertEqual(value['Visible'], [{'Label': 'Original', 'Values': [1, 2]}])
        value['Visible'][0]['Values'].append(4)
        self.assertEqual(result['Visible'][0]['Values'], [1, 2, 3])


