import csv
import io


def _format_cell(value):
    if value is None:
        return ""
    if isinstance(value, str) and value.lstrip(" \t").startswith(("=", "+", "-", "@")):
        return "'" + value
    return str(value)


def export_csv(rows, columns):
    """Export ordered columns as CSV, protecting string cells from formulas."""
    columns = tuple(columns)
    record = io.StringIO(newline="")
    writer = csv.writer(record, lineterminator="\r\n")
    lines = []

    def append_record(values):
        writer.writerow(_format_cell(value) for value in values)
        # CRLF makes the writer quote both CR and LF within cells. Change only
        # the record terminator so embedded line endings remain untouched.
        lines.append(record.getvalue()[:-2] + "\n")
        record.seek(0)
        record.truncate(0)

    append_record(columns)
    for row in rows:
        append_record(row.get(column) for column in columns)
    return "".join(lines)

