from utilities.duration import parse_duration


class ParseDurationTests(unittest.TestCase):
    def test_single_components(self):
        for text, seconds in (
            ("2h", 7200), ("15m", 900), ("45s", 45),
            ("0h", 0), ("0m", 0), ("0s", 0),
        ):
            with self.subTest(text=text):
                self.assertEqual(parse_duration(text), seconds)

    def test_ordered_combinations_and_omitted_units(self):
        for text, seconds in (
            ("2h15m", 8100), ("1h0m4s", 3604), ("1h4s", 3604),
            ("2m3s", 123), ("0h0m0s", 0), ("00h001m0002s", 62),
        ):
            with self.subTest(text=text):
                self.assertEqual(parse_duration(text), seconds)

    def test_components_may_exceed_clock_ranges(self):
        self.assertEqual(parse_duration("90h123m456s"), 331836)

    def test_components_exceed_integer_string_conversion_limits(self):
        digits = "1" + "0" * 5000
        for unit, multiplier in (("h", 3600), ("m", 60), ("s", 1)):
            with self.subTest(unit=unit):
                self.assertEqual(parse_duration(digits + unit), 10 ** 5000 * multiplier)

    def test_repeated_and_reordered_units_are_rejected(self):
        for text in (
            "1h2h", "1m2m", "1s2s", "1m2h", "1s2m", "1s2h",
            "1h2s3m", "0h0h", "0m0h", "1h2m3s4h",
        ):
            with self.subTest(text=text):
                with self.assertRaises(ValueError):
                    parse_duration(text)

    def test_malformed_components_are_rejected(self):
        for text in (
            "", "h", "1", "1h2", "1hms", "1H", "1d", "1h!", "1s\x00",
            "+1h", "-1h", "1h+2m", "1h-2m", "1.5h", ".5s", "1e3s",
            " 1h", "1h ", "1 h", "1h 2m", "\t1s", "1s\n", "1\ns",
            "1h\t2m", "1h\n2m", "\u00a01s", "1_000s",
        ):
            with self.subTest(text=text):
                with self.assertRaises(ValueError):
                    parse_duration(text)

    def test_non_ascii_digits_are_rejected(self):
        for text in ("١s", "１h", "²s", "1m٤s", "1h۲m3s"):
            with self.subTest(text=text):
                with self.assertRaises(ValueError):
                    parse_duration(text)

    def test_non_strings_are_rejected_with_value_error(self):
        for value in (None, 1, 1.5, True, b"1s", ["1s"], {"s": 1}, ("1s",)):
            with self.subTest(value=value):
                with self.assertRaises(ValueError):
                    parse_duration(value)

