        value = {"empty_dict": {}, "empty_list": [], "nested": [{}]}
        result = redact(value, iter(()))
        self.assertEqual(result, value)
        self.assertIsNot(result, value)
        self.assertIsNot(result["empty_dict"], value["empty_dict"])
        self.assertIsNot(result["empty_list"], value["empty_list"])
        self.assertIsNot(result["nested"], value["nested"])
        self.assertIsNot(result["nested"][0], value["nested"][0])

