def redact(value, sensitive_keys):
    """Copy a JSON-like tree, replacing values under sensitive keys."""
    normalized_keys = {key.casefold() for key in sensitive_keys}

    def visit(node):
        if isinstance(node, dict):
            return {
                key: "[REDACTED]"
                if isinstance(key, str) and key.casefold() in normalized_keys
                else visit(child)
                for key, child in node.items()
            }
        if isinstance(node, list):
            return [visit(child) for child in node]
        return node

    return visit(value)

